BEGIN;

CREATE TABLE character_skills (
  campaign_id uuid NOT NULL,
  character_id uuid NOT NULL,
  skill_index text NOT NULL,
  proficient boolean NOT NULL DEFAULT false,
  expertise boolean NOT NULL DEFAULT false,
  PRIMARY KEY (campaign_id, character_id, skill_index),
  FOREIGN KEY (campaign_id, character_id) REFERENCES characters(campaign_id, id)
);

CREATE TABLE campaign_spells (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id uuid NOT NULL REFERENCES campaigns(id),
  created_by uuid NOT NULL,
  name text NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 200),
  level integer NOT NULL CHECK (level BETWEEN 0 AND 9),
  school text NOT NULL CHECK (length(trim(school)) BETWEEN 1 AND 100),
  casting_time text NOT NULL DEFAULT '' CHECK (length(casting_time) <= 200),
  range text NOT NULL DEFAULT '' CHECK (length(range) <= 200),
  components text NOT NULL DEFAULT '' CHECK (length(components) <= 200),
  material text CHECK (material IS NULL OR length(material) <= 500),
  duration text NOT NULL DEFAULT '' CHECK (length(duration) <= 200),
  concentration boolean NOT NULL DEFAULT false,
  ritual boolean NOT NULL DEFAULT false,
  classes text NOT NULL DEFAULT '' CHECK (length(classes) <= 300),
  description text NOT NULL DEFAULT '' CHECK (length(description) <= 20000),
  higher_level text CHECK (higher_level IS NULL OR length(higher_level) <= 5000),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (campaign_id, id),
  FOREIGN KEY (campaign_id, created_by) REFERENCES campaign_members(campaign_id, user_id)
);

CREATE INDEX campaign_spells_campaign ON campaign_spells(campaign_id);

CREATE TABLE character_spells (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id uuid NOT NULL,
  character_id uuid NOT NULL,
  source text NOT NULL CHECK (source IN ('srd','custom')),
  srd_index text,
  custom_spell_id uuid,
  prepared boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (
    (source = 'srd' AND srd_index IS NOT NULL AND custom_spell_id IS NULL) OR
    (source = 'custom' AND custom_spell_id IS NOT NULL AND srd_index IS NULL)
  ),
  FOREIGN KEY (campaign_id, character_id) REFERENCES characters(campaign_id, id),
  FOREIGN KEY (campaign_id, custom_spell_id) REFERENCES campaign_spells(campaign_id, id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX character_spells_srd_unique
  ON character_spells(character_id, srd_index) WHERE source = 'srd';
CREATE UNIQUE INDEX character_spells_custom_unique
  ON character_spells(character_id, custom_spell_id) WHERE source = 'custom';
CREATE INDEX character_spells_character ON character_spells(campaign_id, character_id);

CREATE TABLE srd_spell_translations (
  srd_index text PRIMARY KEY,
  name_ru text,
  desc_ru text,
  higher_level_ru text,
  flagged boolean NOT NULL DEFAULT false,
  flagged_by uuid,
  translated_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE, DELETE
  ON character_skills, campaign_spells, character_spells, srd_spell_translations
  TO ttrpg_app;

INSERT INTO srd_spell_translations (srd_index, name_ru, desc_ru, higher_level_ru) VALUES
  ('fire-bolt', 'Огненный снаряд', 'Вы бросаете в существо или предмет в пределах дистанции сгусток огня. Совершите дальнобойную атаку заклинанием по цели. При попадании цель получает 1d10 урона огнём. Воспламеняющийся предмет, поражённый этим заклинанием, загорается, если его никто не носит и не держит в руках.

Урон от этого заклинания увеличивается на 1d10, когда вы достигаете 5 уровня (2d10), 11 уровня (3d10) и 17 уровня (4d10).', NULL),
  ('mage-hand', 'Магическая рука', 'Призрачная парящая рука появляется в выбранной вами точке в пределах дистанции и существует, пока заклинание активно, либо пока вы не отмените его действием. Рука исчезает, если окажется более чем в 30 футах от вас или если вы сотворите это заклинание ещё раз.

Вы можете действием управлять рукой. Вы можете использовать руку, чтобы манипулировать предметом, открывать незапертую дверь или контейнер, убирать предмет в открытый контейнер или доставать его оттуда, а также выливать содержимое сосуда. При каждом использовании руки вы можете переместить её на 30 футов.

Рука не может атаковать, активировать магические предметы или переносить более 10 фунтов.', NULL),
  ('prestidigitation', 'Фокусы', 'Это заклинание — простейший фокус, который начинающие волшебники используют для практики. Вы создаёте один из следующих магических эффектов в пределах дистанции: мгновенный безвредный эффект чувств (искры, порыв ветра, тихая музыка); мгновенно зажигаете или тушите свечу, факел или маленький костёр; мгновенно очищаете или пачкаете предмет объёмом не более 1 кубического фута; охлаждаете, нагреваете или ароматизируете 1 кубический фут неживой материи на 1 час; создаёте на предмете или поверхности небольшую цветную отметину или символ на 1 час; создаёте нементальный трюк-сенсацию, не имеющий игрового эффекта.

Это заклинание, если вы сотворите его несколько раз, позволяет вам поддерживать одновременно до трёх его нементальных эффектов.', NULL),
  ('guidance', 'Наставление', 'Вы касаетесь согласного на то существа. Один раз до окончания заклинания цель может бросить одну d4 и прибавить результат к одной проверке характеристики по своему выбору. Цель может бросить кость до или после совершения проверки. После этого заклинание оканчивается.', NULL),
  ('sacred-flame', 'Священное пламя', 'Пламя, льющееся с небес, обрушивается на существо, которое вы видите в пределах дистанции. Цель должна успешно пройти спасбросок Ловкости, иначе получит 1d8 урона излучением. Заклинание игнорирует укрытие цели.', NULL),
  ('eldritch-blast', 'Мистический заряд', 'Луч потрескивающей энергии устремляется к существу в пределах дистанции. Совершите дальнобойную атаку заклинанием по цели. При попадании цель получает 1d10 урона силовым полем.

Заклинание создаёт больше одного луча, когда вы достигаете более высоких уровней: два луча на 5 уровне, три луча на 11 уровне и четыре луча на 17 уровне. Вы можете направлять лучи в одну цель или в разные.', NULL),
  ('minor-illusion', 'Малая иллюзия', 'Вы создаёте звук или образ предмета в пределах дистанции, который длится всё время сотворения заклинания. Иллюзия также оканчивается, если вы отмените её действием или сотворите это заклинание снова.

Если вы создаёте звук, его громкость может варьироваться от шёпота до крика. Он может быть вашим голосом, чужим голосом, львиным рыком, боем барабанов или любым другим избранным вами звуком. Звук длится непрерывно всё время действия заклинания, либо вы можете посылать прерывистые звуки в разное время до окончания заклинания.

Если вы создаёте образ предмета — например, стула, грязных следов или небольшого сундука, — он не может быть больше куба с длиной ребра 5 футов. Образ не может издавать звук, свет, запах или иные эффекты восприятия. Физическое взаимодействие с образом обнаруживает, что он является иллюзией, поскольку сквозь него можно провести руку.', NULL),
  ('light', 'Свет', 'Вы касаетесь одного предмета, размер которого не превышает 10 футов ни по одному из измерений. Пока заклинание активно, предмет испускает яркий свет в радиусе 20 футов и тусклый свет ещё в пределах 20 футов. Свет может быть любого цвета по вашему выбору. Полное укрытие предмета блокирует свет. Заклинание оканчивается, если вы сотворите его снова или отмените его действием.

Если вы направите заклинание на предмет, удерживаемый или носимый враждебным существом, это существо должно успешно пройти спасбросок Ловкости, чтобы избежать эффекта заклинания.', NULL),
  ('mending', 'Починка', 'Это заклинание чинит один разрыв или пробоину в предмете, которого вы касаетесь, например, порванное звено цепи, две половины сломанного ключа, разорванный плащ или прохудившийся бурдюк. Если разрыв или пробоина не превышает 1 фута в любом измерении, заклинание чинит её, не оставляя следов повреждения.

Это заклинание может физически чинить магический предмет или конструкцию, но не восстанавливает магию такого предмета.', NULL),
  ('vicious-mockery', 'Жестокая насмешка', 'Вы насылаете поток язвительных оскорблений, пропитанных тонкой магией, на существо, которое видите в пределах дистанции. Если цель может вас слышать (хотя и не обязана понимать ваш язык), она должна успешно пройти спасбросок Мудрости, иначе получит 1d4 урона психической энергией и получит помеху на следующий бросок атаки до конца своего следующего хода.', NULL),
  ('magic-missile', 'Волшебная стрела', 'Вы создаёте три светящихся дротика магической силы. Каждый дротик поражает существо по вашему выбору, видимое вами в пределах дистанции. Дротик наносит цели 1d4+1 урона силовым полем. Все дротики попадают в цели одновременно, и вы можете направить их в одно существо или в нескольких.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 2 уровня или выше, заклинание создаёт по одному дополнительному дротику за каждый уровень ячейки выше первого.'),
  ('cure-wounds', 'Лечение ран', 'Существо, которого вы касаетесь, восстанавливает количество хитов, равное 1d8 + ваш модификатор базовой характеристики. Это заклинание не действует на нежить и конструктов.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 2 уровня или выше, лечение увеличивается на 1d8 за каждый уровень ячейки выше первого.'),
  ('shield', 'Щит', 'Незримая сила образует вокруг вас магический барьер, который сохраняется до начала вашего следующего хода. До этого момента вы получаете бонус +5 к КД, включая атаку, вызвавшую срабатывание заклинания, а также не получаете урон от Волшебной стрелы.', NULL),
  ('healing-word', 'Исцеляющее слово', 'Существо по вашему выбору, которое вы видите в пределах дистанции, восстанавливает хиты в количестве 1d4 + ваш модификатор базовой характеристики. Это заклинание не действует на нежить и конструктов.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 2 уровня или выше, лечение увеличивается на 1d4 за каждый уровень ячейки выше первого.'),
  ('mage-armor', 'Доспехи мага', 'Вы касаетесь согласного на то существа, не носящего доспехов, и на него нисходит защитная магическая сила, которая сохраняется до окончания заклинания. Базовый КД цели становится равен 13 + модификатор Ловкости. Заклинание оканчивается, если цель надевает доспехи или вы отменяете заклинание действием.', NULL),
  ('detect-magic', 'Обнаружение магии', 'Пока заклинание активно, вы ощущаете присутствие магии в пределах 30 футов от себя. Если вы ощущаете магию таким образом, вы можете действием увидеть слабое свечение вокруг видимого существа или предмета в области, несущего магию, а также узнать школу магии, если она есть.

Заклинание можно заблокировать 1 футом камня, обычного дерева или земли, 1 дюймом металла или тонким слоем свинца.', NULL),
  ('bless', 'Благословение', 'Вы благословляете до трёх существ по вашему выбору в пределах дистанции. Каждый раз, когда цель совершает бросок атаки или спасбросок до окончания действия заклинания, она может прибавить к результату броска 1d4.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 3 уровня или выше, вы можете воздействовать на одно дополнительное существо за каждый уровень ячейки выше второго.'),
  ('faerie-fire', 'Огни фей', 'Все предметы в кубе с длиной ребра 20 футов в пределах дистанции вспыхивают голубым, зелёным или фиолетовым светом по вашему выбору (яркий свет). Все существа в области также вспыхивают светом, если проваливают спасбросок Ловкости. До окончания заклинания все освещённые предметы и существа излучают тусклый свет в радиусе 10 футов.

Любой бросок атаки по освещённому существу или предмету совершается с преимуществом, если атакующий видит цель, а освещённое существо не может извлечь выгоду из невидимости.', NULL),
  ('thunderwave', 'Громовая волна', 'От вас исходит волна громового звука. Все существа в кубе с длиной ребра 15 футов от вас должны совершить спасбросок Телосложения. При провале существо получает 2d8 урона звуком и отталкивается на 10 футов от вас. При успехе существо получает половину урона и не отталкивается.

Вдобавок незакреплённые предметы, полностью находящиеся в области действия, автоматически отталкиваются от вас на 10 футов этим заклинанием, и при этом сгенерированный грохот слышен на расстоянии до 300 футов.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 2 уровня или выше, урон увеличивается на 1d8 за каждый уровень ячейки выше первого.'),
  ('hunters-mark', 'Метка охотника', 'Вы выбираете существо, которое видите в пределах дистанции, и магически помечаете его как свою добычу. До окончания заклинания вы наносите цели дополнительно 1d6 урона каждый раз, когда попадаете по ней атакой оружием, а также имеете преимущество на любые проверки Мудрости (Внимательность) или Мудрости (Выживание), совершаемые для поиска цели.

Если цель падает до 0 хитов до истечения заклинания, вы можете действием в следующий свой ход пометить новое существо.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 3 или 4 уровня, вы можете поддерживать концентрацию на заклинании до 8 часов. Используя ячейку 5 уровня или выше, вы можете поддерживать концентрацию на нём вплоть до 24 часов.'),
  ('scorching-ray', 'Опаляющий луч', 'Вы создаёте три луча огня и направляете их в цели в пределах дистанции. Вы можете направить их в одну цель или в разные. Совершите дальнобойную атаку заклинанием по каждой цели. При попадании цель получает 2d6 урона огнём.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 3 уровня или выше, вы создаёте один дополнительный луч за каждый уровень ячейки выше второго.'),
  ('misty-step', 'Туманный шаг', 'Вы окутываетесь серебристым туманом, который мгновенно телепортирует вас на расстояние до 30 футов в место, которое вы видите.', NULL),
  ('hold-person', 'Удержание личности', 'Выберите гуманоида, которого вы видите в пределах дистанции. Цель должна успешно пройти спасбросок Мудрости, иначе будет парализована на время действия заклинания. В конце каждого своего хода цель может повторно совершать спасбросок Мудрости, оканчивая эффект на себе при успехе.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 3 уровня или выше, вы можете воздействовать на одного дополнительного гуманоида за каждый уровень ячейки выше второго. Все гуманоиды должны находиться в пределах 30 футов друг от друга при выборе целей заклинания.'),
  ('invisibility', 'Невидимость', 'Существо, которого вы касаетесь, становится невидимым до окончания заклинания. Всё, что цель несёт или носит, невидимо, пока находится на ней. Заклинание оканчивается для цели раньше, если она совершает атаку или сотворяет заклинание.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 3 уровня или выше, вы можете воздействовать на одно дополнительное существо за каждый уровень ячейки выше второго.'),
  ('web', 'Паутина', 'Вы создаёте область липкой паутины в точке по вашему выбору в пределах дистанции. Паутина заполняет куб с длиной ребра 20 футов и существует, пока действует заклинание. Паутина является труднопроходимой местностью и слабо блокирует обзор сквозь себя.

Если паутина не закреплена между двумя достаточно прочными поверхностями (например, двумя стенами) или не наложена на пол, потолок или иную горизонтальную поверхность, паутина оседает, и большая её часть повисает на потолке. Существо, оказавшееся в области паутины, когда та появляется, должно преуспеть в спасброске Ловкости, иначе окажется опутано паутиной. Опутанное существо, преуспевшее в спасброске, не оказывается опутано, а лишь перемещается со скоростью, ограниченной труднопроходимой местностью.

Существо, опутанное паутиной, может действием совершить проверку Силы против Сложности вашего заклинания. При успехе оно освобождается.

Липкая паутина легко воспламеняется. Любая область паутины, поражённая источником огня, немедленно вспыхивает. Все существа в области паутины при начале хода в огне получают 2d4 урона огнём.', NULL),
  ('spiritual-weapon', 'Духовное оружие', 'Вы создаёте парящее магическое оружие в пределах дистанции, которое существует до окончания заклинания или пока вы не сотворите его снова. Когда вы сотворяете заклинание, вы можете атаковать существо в пределах 5 футов от оружия. Совершите атаку заклинанием по цели. При попадании цель получает урон силовым полем, равный 1d8 + модификатор базовой характеристики.

В качестве бонусного действия в свой ход вы можете переместить оружие на 20 футов, а затем повторить атаку по существу в пределах 5 футов от него.', 'Урон от заклинания увеличивается на 1d8, когда вы достигаете 5 уровня (2d8), 11 уровня (3d8) и 17 уровня (4d8).'),
  ('fireball', 'Огненный шар', 'Яркая вспышка вырывается из точки по вашему выбору в пределах дистанции, а затем со свистом расширяется огненным шаром с радиусом 20 футов вокруг этой точки. Все существа в области взрыва должны совершить спасбросок Ловкости. При провале существо получает 8d6 урона огнём, при успехе — половину урона.

Огонь поджигает горючие предметы в области, не носимые и не удерживаемые никем.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 4 уровня или выше, урон увеличивается на 1d6 за каждый уровень ячейки выше третьего.'),
  ('counterspell', 'Контрзаклинание', 'Вы совершаете жест и произносите резкие слова, пытаясь помешать существу сотворить заклинание. Если существо сотворяет заклинание 3 уровня или ниже, его заклинание проваливается и не имеет эффекта. Если оно сотворяет заклинание 4 уровня или выше, совершите проверку базовой характеристики. Сложность равна 10 + уровень заклинания. При успехе сотворяемое заклинание проваливается и не имеет эффекта.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 4 уровня или выше, прерываемое заклинание автоматически проваливается, если его уровень равен или меньше уровня использованной вами ячейки.'),
  ('fly', 'Полёт', 'Существо, которого вы касаетесь, получает скорость полёта 60 футов на время действия заклинания. Когда заклинание оканчивается, цель падает, если по-прежнему находится в воздухе, кроме случаев, когда она способна остановить падение.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 4 уровня или выше, вы можете воздействовать на одно дополнительное существо за каждый уровень ячейки выше третьего.'),
  ('dispel-magic', 'Рассеивание магии', 'Выберите одно существо, предмет или магический эффект, видимый вами в пределах дистанции. Любое заклинание 3 уровня или ниже, действующее на цель, оканчивается. Для каждого заклинания 4 уровня или выше, действующего на цель, совершите проверку базовой характеристики. Сложность равна 10 + уровень заклинания. При успехе действие заклинания на цель оканчивается.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 4 уровня или выше, вы автоматически оканчиваете действие заклинания на цели, если уровень этого заклинания равен или меньше уровня использованной вами ячейки.'),
  ('lightning-bolt', 'Молния', 'Из вас исходит вспышка молнии в виде линии длиной 100 футов и шириной 5 футов в выбранном вами направлении. Все существа на этой линии должны совершить спасбросок Ловкости. При провале существо получает 8d6 урона электричеством, при успехе — половину урона.

Молния поджигает горючие предметы в области, не носимые и не удерживаемые никем.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 4 уровня или выше, урон увеличивается на 1d6 за каждый уровень ячейки выше третьего.'),
  ('polymorph', 'Полиморф', 'Это заклинание превращает существо, которое вы видите в пределах дистанции, в новую форму. Нежелающее цели существо должно совершить спасбросок Мудрости, чтобы избежать этого эффекта. Оборотень или существо с 0 хитов автоматически преуспевает в спасброске.

Эффект длится до окончания заклинания, либо пока хиты цели в новой форме не опустятся до 0, либо пока цель не умрёт. Новая форма может быть любым существом, чей показатель опасности равен или меньше показателя опасности цели (или её уровню, если у неё нет показателя опасности). Игровая статистика цели, включая психические характеристики, заменяется статистикой избранного существа, однако мировоззрение и личность цели сохраняются. Цель принимает хиты новой формы. Когда она возвращается в свою обычную форму, она возвращается в то количество хитов, которое имела до превращения.', NULL),
  ('wall-of-fire', 'Стена огня', 'Вы создаёте стену пылающего огня в точке, которую видите в пределах дистанции. Стена может быть прямой панелью до 60 футов длиной, 20 футов высотой и 1 фут толщиной, либо кольцом до 20 футов диаметром, 20 футов высотой и 1 фут толщиной. Стена непрозрачна и существует до окончания заклинания.

Когда стена появляется, каждое существо в её начальной области должно совершить спасбросок Ловкости. При провале существо получает 5d8 урона огнём, при успехе — половину урона.

Одна сторона стены, выбираемая вами при сотворении заклинания, наносит 5d8 урона огнём существам, оканчивающим ход в пределах 10 футов от этой стороны либо совершающим по ней атаку в ближнем бою, либо проходящим сквозь стену. Другая сторона не наносит урона.', 'Когда вы сотворяете это заклинание, используя ячейку заклинания 5 уровня или выше, урон увеличивается на 1d8 за каждый уровень ячейки выше четвёртого.'),
  ('haste', 'Ускорение', 'Выберите согласное на то существо, которое вы видите в пределах дистанции. До окончания заклинания скорость цели удваивается, она получает бонус +2 к КД, преимущество на спасброски Ловкости, а также получает дополнительное действие в каждый свой ход. Этим действием цель может только совершить действие Атака (только одна атака оружием), Рывок, Отход, Засада или Применение предмета.

Когда заклинание оканчивается, цель не может двигаться и не может совершать действия до конца своего следующего хода, поскольку на неё накатывает временное истощение.', NULL)
